/* Módulo: js/repairs-v23.js | Función: lógica original del bloque 34 | Depende de: scripts anteriores en orden de carga | Expone: declaraciones y efectos globales originales, cuando corresponda. */

(function(){
'use strict';
const DEFAULT_LOGO='data:image/png;base64,';window.VIBRA_DEFAULT_LOGO=DEFAULT_LOGO;
const $=sel=>document.querySelector(sel);
// Keep the supplied visual identity when cloud configuration has no logo.
function logo(){const image=$('#brandLogo img');if(image&&(!image.getAttribute('src')||image.getAttribute('src')===''))image.src=DEFAULT_LOGO;
 const icon=$('#brandLogo');if(icon&&!image)icon.innerHTML='<img src="'+DEFAULT_LOGO+'" alt="Logo de VibraErótica">';}
const oldHeader=renderHeader;renderHeader=function(){oldHeader();logo()};logo();
function productsPickupOnly(){try{return cartItems().some(x=>(x.p.deliveryAvailable===false||/cigar|tabaco/i.test(x.p.category||'')))}catch{return false}}
// The shipping option is a user choice, and must stay reversible.
const oldCart=renderCart;
renderCart=function(){if(productsPickupOnly()&&checkout.delivery==='delivery')checkout.delivery='pickup';oldCart();
 const body=$('#cartBody');if(!body)return;
 if(productsPickupOnly()){
  const row=body.querySelector('input[name="delivery"][value="delivery"]');if(row){row.disabled=true;row.closest('.radio-card')?.setAttribute('title','Uno o más artículos solo pueden recogerse en el local');}
  if(!$('#v23PickupWarning')){const info=document.createElement('div');info.id='v23PickupWarning';info.className='notice';info.textContent='Este pedido contiene artículos exclusivos para recoger en el local. Retíralos del carrito para habilitar domicilio.';body.prepend(info)}
 }
 const name=$('#customerName');const session=typeof customerSession!=='undefined'?customerSession:null;
 if(name&&!checkout.name?.trim()&&session?.user){const u=session.user;const display=u.user_metadata?.full_name||u.user_metadata?.name||u.user_metadata?.alias||u.email?.split('@')[0]||'';if(display){checkout.name=display;name.value=display;}}
 if(!$('#v23DeliveryNote')&&body.querySelector('input[name="delivery"]')){const note=document.createElement('p');note.id='v23DeliveryNote';note.className='small muted';note.textContent='Puedes cambiar entre recogida y domicilio mientras los productos permitan entrega.';body.querySelector('input[name="delivery"]').closest('.form-section')?.append(note)}
};
// Keep checkout choice synchronized before the underlying handlers rerender it.
document.addEventListener('change',event=>{if(event.target.matches('input[name="delivery"]')){
 if(event.target.value==='delivery'&&productsPickupOnly()){event.stopImmediatePropagation();checkout.delivery='pickup';renderCart();toast('Un producto de tu carrito es exclusivo del local.','info');return;}
 checkout.delivery=event.target.value;
}},true);
// Product cards receive a clear cart action rather than relying on a small plus icon.
function enhanceProducts(){return;document.querySelectorAll('#catalogGrid .product-card').forEach(card=>{
 const existing=card.querySelector('[data-inc]');if(!existing)return;
 const p=existing.getAttribute('data-inc');const row=card.querySelector('.qty-row');if(!row)return;
 let add=card.querySelector('.v23-cart-add');if(!add){add=document.createElement('button');add.className='v23-cart-add';add.type='button';add.innerHTML='<svg viewBox="0 0 24 24"><path d="M3 4h2l2.2 10.2a2 2 0 0 0 2 1.6h7.7a2 2 0 0 0 1.9-1.4L21 7H6.2"/><circle cx="10" cy="20" r="1.4"/><circle cx="18" cy="20" r="1.4"/></svg><span>Añadir al carrito</span>';add.onclick=()=>{changeQty(p,1);toast('Agregado al carrito','ok')};row.append(add)}
 const item=state.products.find(x=>String(x.id)===String(p));if(item){add.disabled=item.stock<=0||(state.cart[p]||0)>=item.stock;if((item.deliveryAvailable===false||/cigar|tabaco/i.test(item.category||''))&&!card.querySelector('.v23-pickup')){const text=document.createElement('p');text.className='v23-pickup';text.textContent='Solo recoger en el local';card.querySelector('.product-body')?.append(text)}}
 });}
let catalogBusy=false;const cat=$('#catalogGrid');if(cat){new MutationObserver(()=>{if(catalogBusy)return;catalogBusy=true;requestAnimationFrame(()=>{catalogBusy=false;enhanceProducts()})}).observe(cat,{childList:true,subtree:false});enhanceProducts()}
// Provide explicit map rotation where Leaflet's optional rotation plugin is active.
function setupMap(){const el=$('#foodDeliveryMap')||$('#foodAddressMap')||$('#publicMap');if(!el||el.querySelector('#v23MapControls'))return;
 const controls=document.createElement('div');controls.id='v23MapControls';controls.innerHTML='<button type="button" data-turn="-15" title="Girar 15° a la izquierda">↶</button><button type="button" data-turn="15" title="Girar 15° a la derecha">↷</button><button type="button" data-turn="reset" title="Orientar al norte">N</button>';el.append(controls);
 controls.addEventListener('click',e=>{const b=e.target.closest('[data-turn]');if(!b)return;const map=[typeof publicAddressMap!=='undefined'?publicAddressMap:null,typeof clientMap!=='undefined'?clientMap:null,typeof originMap!=='undefined'?originMap:null].find(x=>x&&x.getContainer?.()===el);
 if(!map||typeof map.setBearing!=='function'){toast('La rotación no está disponible en este mapa.','info');return;}const v=b.dataset.turn;map.setBearing(v==='reset'?0:(map.getBearing?.()||0)+Number(v));});
}
const observer=new MutationObserver(()=>{logo();setupMap()});observer.observe(document.body,{subtree:true,childList:true});setupMap();
})();
